INSERT INTO products (id, title, description, price, sale_price, category_id, stock, status, image_url, badge, rating, created_at, updated_at) VALUES
  ('dd365d85-0cb8-4e13-b132-8fbf29dabde9', 'Kishu Nanko Ripe Plum Wine', 'Kishu Nanko Ripe Plum Wine is a rich and refined Japanese plum wine crafted by Nakata, a renowned producer celebrated for its dedication to quality and tradition. Bottled in a generous 720 ml size with a robust 20% alcohol content, this exceptional wine is made from fully ripe Nanko plums, prized for their deep sweetness and intense aroma. It offers a luxurious balance of luscious fruitiness and smooth warmth, delivering a velvety texture and lingering finish. Best enjoyed chilled or neat, Kishu Nanko Ripe Plum Wine is perfect for special occasions or as a sophisticated gift, embodying the artistry and heritage of authentic Japanese plum wines.', 57, NULL, '8d71a882-9348-4e54-9794-5c820c6310dc', NULL, 'published', '/products/kishu-nanko-ripe-plum-wine.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('ad595236-ac3c-4190-859b-3d8f06792683', 'Kishu Nanko Ripe Plum Wine Barrel 5 Years', 'Kishu Nanko Ripe Plum Wine Barrel 5 Years is an exquisite Japanese plum wine aged to perfection by Nakata, a respected producer renowned for its commitment to traditional craftsmanship. Bottled in a 720 ml format with 20% alcohol content, this luxurious wine is made from fully ripe Nanko plums and matured for five years in wooden barrels, which impart rich, complex notes of oak, vanilla, and toasted caramel. The aging process enhances its deep fruity sweetness and smooth, velvety texture, delivering a refined, well-balanced flavor with a long, elegant finish. Best served chilled or neat, this barrel-aged plum wine is an exceptional choice for special occasions and collectors seeking the pinnacle of Japanese plum wine artistry.', 148, NULL, '8d71a882-9348-4e54-9794-5c820c6310dc', NULL, 'published', '/products/kishu-nanko-ripe-plum-wine-5-year.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('b6f65226-6599-451e-9af7-4e96de8a2a52', 'Nakata Kishu Plum wine with fruit', 'Nakata Kishu Plum Wine with Fruit is a refined Japanese plum wine crafted by Nakata, a distinguished producer from Wakayama Prefecture, famed for its premium Kishu ume plums. This elegant 84 ml presentation captures the luscious sweetness and gentle tartness of handpicked plums, enhanced by the visual charm of whole fruit resting inside the bottle. With a smooth 12% alcohol content, it offers a harmonious balance of freshness, aroma, and delicate richness. Best enjoyed chilled, it delivers a refreshing and authentic taste of Japan in every sip. Its petite size makes it a perfect choice for a sophisticated tasting, a unique gift, or an elegant party accent — proof that exceptional flavor can come in the most exquisite packages.', 4, NULL, '8d71a882-9348-4e54-9794-5c820c6310dc', NULL, 'published', '/products/nakata-kishu-plum-wine-with-plum-fruit.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('aefbff64-79ef-4f1f-b8c6-9fdf567f477d', 'Daiyame Imo Shouchu', 'Daiyame Imo Shochu is a premium Japanese sweet potato shochu crafted by Hamada Syuzou, a historic distillery founded in 1868 in Kagoshima Prefecture. Bottled at 25% ABV in a 900 ml format, this honkaku shochu is renowned for its signature lychee-like aroma, achieved through the use of specially aged kōjuku-imo sweet potatoes and traditional black kōji fermentation. Smooth, delicate, and aromatic, it offers a refined balance of gentle sweetness and floral-fruity notes, making it both approachable for newcomers and captivating for connoisseurs. Best enjoyed on the rocks, with chilled water, or as a highball, Daiyame pairs beautifully with light appetizers, seafood, or Japanese cuisine. Recipient of multiple international awards, it represents Hamada Syuzou’s dedication to elevating Kagoshima’s shochu tradition into a modern, globally celebrated spirit.', 25, NULL, '5dc32014-2863-4b7a-a61d-f14243cc35db', NULL, 'published', '/products/daiyame-Imo-Shochu.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('457dbe70-e0aa-4106-a3f6-269497eaadff', 'CHILL GREEN spicy & citrus', 'CHILL GREEN Spicy &amp; Citrus is a premium Japanese sweet potato shochu created by Hamada Syuzou, a renowned distillery founded in 1868 in Kagoshima Prefecture. Bottled at 25% ABV in a 720 ml format, this honkaku shochu is distinguished by its crisp citrus aroma and refreshing herbal-spice character. Crafted with carefully selected sweet potatoes, black kōji, and a unique low-temperature distillation method, it delivers a clean yet invigorating profile with notes of yuzu, green herbs, and subtle peppery warmth. Best enjoyed as a highball with soda or chilled for a vibrant aperitif, CHILL GREEN pairs beautifully with seafood, grilled vegetables, and light Japanese dishes. Celebrated for its modern twist on a centuries-old tradition, it reflects Hamada Syuzou’s innovation in bringing a fresh, contemporary edge to Kagoshima’s shochu heritage.', 25, NULL, '5dc32014-2863-4b7a-a61d-f14243cc35db', NULL, 'published', '/products/chill-green-spicy-citrus.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('d56c0f4d-1f86-4e76-9355-56d341065bb0', 'Akane Kirishima', 'Akane Kirishima is a premium Japanese sweet potato shochu produced by Kirishima Shuzo, one of Japan’s most celebrated distilleries, founded in 1916 in Miyazaki Prefecture. Bottled at 25% ABV in a 900 ml format, this honkaku shochu stands out for its vivid amber hue and elegantly mellow taste. Crafted from carefully selected sweet potatoes, rice kōji, and pristine underground water from the Kirishima mountains, it offers a smooth, slightly sweet profile with gentle notes of roasted chestnut, floral undertones, and a lingering, well-rounded finish. Best enjoyed on the rocks, diluted with hot water, or as a chilled highball, Akane Kirishima pairs beautifully with Japanese home-style dishes, grilled meats, and seasonal vegetables. With its refined balance and distinctive color, it represents Kirishima Shuzo’s dedication to tradition, quality, and innovation in the world of shochu.', 55, NULL, '5dc32014-2863-4b7a-a61d-f14243cc35db', NULL, 'published', '/products/akane-kirishima.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('eb4ddfeb-a45f-47db-84d3-e5e4c3f42384', 'Kurokirishima Shochu Imo', 'Kurokirishima Shochu Imo is a distinguished Japanese sweet potato shochu crafted by Kirishima Shuzo, a historic distillery established in 1916 in Miyazaki Prefecture. Available in a 1.8L bottle with an alcohol content ranging from 20% to 25% ABV, this honkaku shochu is celebrated for its rich, robust flavor and deep amber color. Made using carefully selected sweet potatoes and traditional black koji fermentation, it delivers a full-bodied taste with earthy, smoky undertones balanced by subtle sweetness and a smooth finish. Versatile and approachable, Kurokirishima is ideal for sipping neat, on the rocks, or diluted with hot water, and pairs excellently with grilled meats, hearty stews, and flavorful Japanese dishes. Representing Kirishima’s commitment to craftsmanship and quality, it remains a beloved classic in the world of imo shochu.', 40.5, NULL, '5dc32014-2863-4b7a-a61d-f14243cc35db', NULL, 'published', '/products/kurokirishima-shochu-imo-2.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('3a889792-e854-42d0-a9e2-a1bf14efa3ca', 'Akakirishima Shochu Imo', 'Akakirishima Shochu Imo is a high-quality Japanese sweet potato shochu crafted by Kirishima Shuzo, a distinguished distillery founded in 1916 in Miyazaki Prefecture. Available in a 900 ml bottle with 25% alcohol by volume, this authentic honkaku shochu is recognized by its striking red label and rich, full-flavored character. Made from carefully selected sweet potatoes and traditional black kōji fermentation, it delivers a well-balanced blend of earthy sweetness, gentle smokiness, and a smooth, enduring finish. Ideal for sipping neat, over ice, or diluted with warm water, Akakirishima complements grilled foods, hearty stews, and traditional Japanese dishes. This shochu embodies Kirishima’s commitment to craftsmanship and heritage, making it a popular choice among fans of sweet potato shochu.', 35, NULL, '5dc32014-2863-4b7a-a61d-f14243cc35db', NULL, 'published', '/products/akakirishima-shochu-imo.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('9b58936c-92d6-4dae-9932-d78edac0179d', 'Satsuma Kuroshiranami', 'Satsuma Kuroshiranami is a premium Japanese sweet potato shochu produced by Suntory, a renowned beverage company with a rich history of craftsmanship. Bottled at 25% ABV in a 720 ml format, this honkaku shochu features a robust and full-bodied flavor profile. Made using carefully selected sweet potatoes and traditional black kōji fermentation, it offers deep earthy and smoky notes balanced by a smooth, clean finish. Perfect enjoyed neat, on the rocks, or diluted with warm water, Satsuma Kuroshiranami pairs beautifully with grilled dishes, hearty stews, and classic Japanese cuisine. This shochu has earned recognition at several prestigious competitions, including winning medals at the International Wine &amp; Spirits Competition (IWSC) and the San Francisco World Spirits Competition (SFWSC), underscoring Suntory’s commitment to quality and innovation in Japanese spirits.', 25, NULL, '5dc32014-2863-4b7a-a61d-f14243cc35db', NULL, 'published', '/products/satsuma-kuroshiranami.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('c1627156-e5a9-4417-a6a6-760fe6e7be4b', 'Iichiko silhouette', 'Iichiko Silhouette is a premium Japanese barley shochu crafted by Iichiko, a leading shochu producer known for quality and innovation. Bottled at 25% ABV in a 720 ml format, this honkaku shochu is celebrated for its clean, smooth taste and light, refreshing aroma. Made using carefully selected barley and traditional distillation techniques, Iichiko Silhouette delivers a well-balanced profile with subtle nutty and floral notes, making it highly versatile and easy to enjoy. Best served neat, on the rocks, or diluted with water, it pairs perfectly with a wide range of dishes from light seafood to grilled meats. This shochu has garnered acclaim at international spirits competitions, reflecting Iichiko’s dedication to craftsmanship and excellence.', 25, NULL, '5dc32014-2863-4b7a-a61d-f14243cc35db', NULL, 'published', '/products/Iichiko-silhouette.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('e89522eb-5be1-46ab-951a-c2e71897d057', 'Unkai Kuromaru', 'Unkai Kuromaru is a premium Japanese sweet potato shochu produced by Unkai, a distinguished distillery dedicated to traditional craftsmanship. Bottled at 25% ABV in a 700 ml format, this honkaku shochu is known for its rich, full-bodied flavor and deep aromatic profile. Made with carefully selected sweet potatoes and fermented using black kōji mold, it offers a smooth balance of earthy, smoky, and subtly sweet notes. Ideal for sipping neat, on the rocks, or diluted with warm water, Unkai Kuromaru pairs beautifully with grilled dishes, hearty stews, and classic Japanese cuisine. This shochu reflects Unkai’s commitment to quality and heritage in the world of imo shochu.', 25, NULL, '5dc32014-2863-4b7a-a61d-f14243cc35db', NULL, 'published', '/products/unkai-kuromaru.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('0adfe56a-690c-4c10-966d-0e9021b984f5', 'Umeshu Honey', 'Umeshu Honey is a premium Japanese plum liqueur crafted by Nakano, renowned for blending tradition with natural ingredients. Bottled at 12% ABV in a 720 ml format, this sweet and aromatic liqueur is made by steeping ripe ume plums in high-quality alcohol and natural honey, resulting in a rich balance of fruity tartness and smooth honey sweetness. With its golden amber color and inviting floral aroma, Umeshu Honey is perfect served chilled, poured over ice cubes (“on the rocks”), or mixed in cocktails. It pairs wonderfully with light desserts, cheese, and Asian cuisine. This liqueur showcases Nakano’s dedication to authentic flavor and quality craftsmanship.', 25, NULL, '8d71a882-9348-4e54-9794-5c820c6310dc', NULL, 'published', '/products/umeshu-honey.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('777da4e9-1173-4b52-97f5-d2a8efb55417', 'Umeshu Kisyu (Plum In)', 'Umeshu Kisyu (Plum In) is a sweet and tasty Japanese plum liqueur made by Choya. It comes in a 720 ml bottle with 14% alcohol. This drink is made by soaking whole ripe plums in alcohol and natural sugar, giving it a delicious mix of sweet and sour flavors. It has a smooth texture and a lovely fruity smell. You can enjoy it cold, with ice, or mixed in your favorite drinks. It goes well with desserts and light meals. Choya is famous for making high-quality plum drinks, and this one is a great example.', 24, NULL, '8d71a882-9348-4e54-9794-5c820c6310dc', NULL, 'published', '/products/choya-kishu-plum-wine.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('c5b10707-cda6-427b-817f-e14d5b993ecd', 'Umesyu Reasonable', 'Umeshu Reasonable by Suntory is a delightful Japanese plum liqueur presented in a generous 2-liter bottle with a smooth 8% alcohol content. Crafted by steeping ripe ume plums in high-quality alcohol with a touch of natural sweetness, this liqueur offers a perfectly balanced flavor—refreshingly sweet with a gentle tang. Its inviting fruity aroma and smooth, light texture make it ideal for everyday enjoyment, whether chilled, on the rocks, or mixed into cocktails. Perfect for sharing at gatherings or relaxing moments, Umeshu Reasonable delivers authentic Japanese taste at great value, making it a favorite choice for both new and seasoned umeshu lovers.', 20.5, NULL, '8d71a882-9348-4e54-9794-5c820c6310dc', NULL, 'published', '/products/suntory-shimasenka-plum-wine.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('7dea48b8-c65e-4504-a9f8-9a16c5f5856a', 'Umesyu Tantakatan', 'Umeshu Tantakatan is a premium Japanese plum liqueur crafted by Godo Shusei, renowned for its rich heritage and dedication to quality. Bottled in a sleek 720 ml bottle at 12% ABV, this luscious umeshu blends carefully selected ripe ume plums with a perfect balance of sweetness and tartness. It offers a vibrant aroma bursting with fresh fruit notes and a silky-smooth finish that delights the palate. Whether enjoyed chilled, on the rocks, or mixed in cocktails, Umeshu Tantakatan is the perfect companion for celebrations or relaxing moments. Experience the authentic taste of Japan with every sip of this exquisite, handcrafted plum liqueur.', 22, NULL, '8d71a882-9348-4e54-9794-5c820c6310dc', NULL, 'published', '/products/tantakatan-plum-wine.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('552b1217-dbe8-4340-a9da-7a5f9c6fde2f', 'Umesyu Green tea', 'Umeshu Green Tea by Nakano is a refreshing and elegant Japanese plum liqueur infused with the delicate flavor of green tea. Bottled in a 720 ml bottle with 12% alcohol, this unique blend combines the natural sweetness and tartness of ripe ume plums with the soothing, earthy notes of premium green tea leaves. The result is a smooth, vibrant drink with a subtle herbal aroma and a perfectly balanced taste that’s both invigorating and calming. Ideal served chilled or over ice, Umeshu Green Tea is a sophisticated choice for those seeking a refreshing twist on traditional plum liqueur. Perfect for pairing with light snacks, sushi, or relaxing moments.', 22, NULL, '8d71a882-9348-4e54-9794-5c820c6310dc', NULL, 'published', '/products/plum-wine-with-green-tea.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('446c7994-ab02-4113-b14d-0ddeb29c39a2', 'Umesyu black sugar', 'Umeshu Black Sugar by Choya is a rich and luxurious Japanese plum liqueur, presented in a 700 ml bottle with a smooth 15% alcohol content. Crafted with premium ripe ume plums and blended with deep, flavorful Okinawan black sugar, this umeshu offers a unique harmony of sweet, caramel-like richness and the signature tartness of plum. Its dark amber color and warm, inviting aroma make every sip a decadent experience. Perfect served chilled or on the rocks, Umeshu Black Sugar delivers a bold yet balanced flavor that pairs beautifully with desserts, cheese, or enjoyed on its own. Discover the indulgence of this exquisite blend that elevates traditional umeshu to a new level of sophistication.', 25, NULL, '8d71a882-9348-4e54-9794-5c820c6310dc', NULL, 'published', '/products/umesyu-black-sugar.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('61ad08cb-f97b-4df3-9e10-859cf97fc68f', 'Kishu Plum Wine (white)', 'Kishu Plum Wine (White) by Nakata is a charming and elegant Japanese plum wine, presented in a convenient 180 ml bottle with 12% alcohol content. Crafted from ripe, handpicked Kishu ume plums, renowned for their rich aroma and gentle tartness—this wine offers a soft golden hue and a smooth, mellow flavor profile. Delicately sweet with a refreshing fruitiness, it’s perfect for casual sipping, whether chilled, on the rocks, or paired with light appetizers and desserts. Its compact size makes it ideal for personal enjoyment or as a thoughtful gift, capturing the essence of Japan’s celebrated ume tradition in every sip.', 5, NULL, '8d71a882-9348-4e54-9794-5c820c6310dc', NULL, 'published', '/products/kishu-plum-wine-white.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('80a173a2-e514-4ea5-936f-0be4c1eb2441', 'Kishu Plum Wine (Red)', 'Kishu Plum Wine (Red) is a distinguished Japanese plum wine produced by Nakata, a respected name known for its commitment to quality and tradition. Presented in a refined 180 ml bottle with 12% alcohol content, this vibrant red plum wine is crafted using carefully selected Kishu ume plums, renowned for their rich aroma and balanced sweetness. The wine showcases a harmonious blend of fruity depth and gentle tartness, complemented by a smooth, velvety finish. Best enjoyed chilled or over ice, it pairs beautifully with light desserts and celebratory occasions. With its elegant presentation and authentic flavor, Kishu Plum Wine (Red) exemplifies the finest of Japanese umeshu craftsmanship.', 5.5, NULL, '8d71a882-9348-4e54-9794-5c820c6310dc', NULL, 'published', '/products/kishu-plum-wine-red-.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('5492a2c2-0a82-496f-a07b-20e507c72f78', 'Premium Plum Wine', 'Premium Plum Wine is a refined Japanese plum liqueur crafted by Nakata, a distinguished producer celebrated for its dedication to quality and tradition. Bottled in a 720 ml size at 12% alcohol, this elegant wine is made from carefully selected ripe ume plums, delivering a harmonious balance of natural sweetness and subtle tartness. It offers a smooth, velvety texture with fragrant floral and fruity aromas, creating a rich yet delicate flavor profile. Best enjoyed chilled or on the rocks, Premium Plum Wine is perfect for special occasions or as a thoughtful gift, embodying the artistry and heritage of authentic Japanese umeshu.', 25.5, NULL, '8d71a882-9348-4e54-9794-5c820c6310dc', NULL, 'published', '/products/premium-plum-wine.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('b9b184cc-4254-41d3-9ced-1b26346d0edc', 'Rich Kishu Plum wine with fruit', 'Rich Kishu Plum Wine with Fruit is a luxurious Japanese plum wine crafted by Nakata, a respected producer known for premium ume products. Bottled in a generous 720 ml size at 12% alcohol, this exquisite wine features carefully selected Kishu ume plums along with whole fruit inside the bottle, enhancing its rich aroma and vibrant flavor. It delivers a perfect balance of natural sweetness and gentle tartness, with a smooth, velvety texture and a fragrant, fruity bouquet. Best enjoyed chilled or over ice, Rich Kishu Plum Wine with Fruit offers an authentic taste of Japan, ideal for celebrations, gifting, or savoring special moments.', 22.5, NULL, '8d71a882-9348-4e54-9794-5c820c6310dc', NULL, 'published', '/products/rich-kishu-plum-wine-with-fruit.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('e0759dfe-7182-4cce-b562-755e002aedc6', 'Yokubarihime Torokoku mix', 'Yokubarihime Torokoku Mix is a delightful Japanese plum wine blend crafted by Nakata, renowned for its exceptional umeshu creations. Bottled in a convenient 180 ml size with 12% alcohol, this unique liqueur combines the rich sweetness of ripe Kishu plums with a harmonious mix of tropical fruit flavors. The result is a smooth, refreshing drink with a vibrant aroma and balanced taste that excites the palate. Perfect served chilled or over ice, Yokubarihime Torokoku Mix is an ideal choice for those seeking a fruity twist on traditional plum wine. Its elegant presentation makes it a charming gift or a sophisticated treat for any occasion.', 5.5, NULL, '8d71a882-9348-4e54-9794-5c820c6310dc', NULL, 'published', '/products/yokubarihime-torokoku-mix.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('6ed4f32c-a5dc-4441-a760-90dd8cfcb73d', 'Momohime Torokoku Plum Wine (peach)', 'Momohime Torokoku Plum Wine (Peach) is a luscious Japanese plum wine crafted by Nakata, blending the natural sweetness of premium Kishu ume plums with the juicy, fragrant essence of ripe peaches. Bottled in a generous 500 ml size at 12% alcohol, this elegant liqueur offers a smooth, velvety texture with a vibrant fruity aroma and a perfectly balanced sweet-tart flavor. Best enjoyed chilled or over ice, Momohime Torokoku Peach Plum Wine provides a refreshing and indulgent experience, ideal for relaxing moments or festive occasions. Its exquisite blend captures the essence of Japan’s rich fruit traditions with every sip.', 15, NULL, '8d71a882-9348-4e54-9794-5c820c6310dc', NULL, 'published', '/products/momohime-torokoku-plum-wine-peach-500ml.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('8bd9f957-fb93-4020-ac52-f836bef56cbe', 'Ringohime Torokoku Plum Wine (Apple)', 'Ringohime Torokoku Plum Wine (Apple) is a delightful Japanese plum wine crafted by Nakata, harmoniously blending the sweet and tart flavors of premium Kishu ume plums with the crisp, refreshing essence of ripe apples. Bottled in a generous 500 ml size at 12% alcohol, this smooth and aromatic liqueur offers a vibrant fruit bouquet and a well-balanced taste that’s both refreshing and indulgent. Best enjoyed chilled or over ice, Ringohime Torokoku Apple Plum Wine is perfect for casual sipping, celebrations, or as a unique gift. Experience the fusion of Japan’s finest plum and apple flavors in every elegant sip.', 15, NULL, '8d71a882-9348-4e54-9794-5c820c6310dc', NULL, 'published', '/products/ringohime-torokoku-plum-wine-apple-500ml.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('795f9356-e3b3-47cc-8c7b-242f31588bee', 'Chuka Wakame 500g', NULL, 7, NULL, 'aeb2307e-f160-461b-9e50-a6f72511cde0', NULL, 'published', '/products/chuka-wakame.webp', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('f2ef0a5a-5f5a-4f34-a478-b7e4322c51ef', 'Edamame 1Kg', NULL, 6, NULL, 'aeb2307e-f160-461b-9e50-a6f72511cde0', NULL, 'published', '/products/edamame.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('86338897-91b9-419a-9538-a25dde643581', 'Dashi Konbu 1Kg', NULL, 39, NULL, 'aeb2307e-f160-461b-9e50-a6f72511cde0', NULL, 'published', '/products/dashi-konbu-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('02cbf9b7-835a-4723-95ca-3d2237d633e1', 'Sashimi Wakame 500g', NULL, 17, NULL, 'aeb2307e-f160-461b-9e50-a6f72511cde0', NULL, 'published', '/products/sashimi-wakame.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('fe8d561f-d007-45b0-858c-2a0914a005b8', 'Roasted Seaweed 100pcs (300g)', NULL, 15, NULL, 'aeb2307e-f160-461b-9e50-a6f72511cde0', NULL, 'published', '/products/roasted-seaweed.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('43e18657-4523-4a36-85f5-198a33466e74', 'Umi Buduo 200g', NULL, 9, NULL, 'aeb2307e-f160-461b-9e50-a6f72511cde0', NULL, 'published', '/products/umi-buduo.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('f81edf7f-2a2f-48a9-a821-4b585e746985', 'Abashiri Ryuhyo Draft Blue', 'Abashiri Ryuhyo Draft Blue is a visually stunning craft beer from Abashiri Beer, inspired by the drift ice of Hokkaido’s Sea of Okhotsk. Brewed with pure Okhotsk water and natural ingredients, its vibrant ocean-blue color comes from gardenia flowers, evoking the icy northern seas. At 5% ABV, this light and crisp beer offers a refreshing taste with a subtle sweetness and a clean finish, perfect for enjoying chilled. The unique color and smooth profile make it a conversation starter at gatherings, pairing beautifully with seafood, light appetizers, or simply enjoyed on its own. More than just a drink, it’s an immersive taste of Hokkaido’s winter landscape, crafted for those who appreciate both flavor and artistry in their beer.', 30, NULL, '1344104a-7f28-4571-8de3-5737fd6b5943', NULL, 'published', '/products/abashiri-ryuhyo-draft-blue-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('3ca11156-181e-4d34-b0d4-2981c01dbd7d', 'Abashiri Shiretoko Draft Green', 'Abashiri Shiretoko Draft Green is a captivating craft beer from Abashiri Beer, inspired by the lush forests and pristine nature of Hokkaido’s Shiretoko Peninsula. Brewed with pure Okhotsk water and natural ingredients, its striking green hue comes from carefully selected botanicals, reflecting the freshness of Hokkaido’s wilderness. At 5% ABV, this smooth and refreshing beer offers a gentle bitterness balanced with subtle herbal notes, making it perfect chilled. Ideal for pairing with salads, seafood, or light appetizers, it delivers a crisp and invigorating experience that brings the essence of Shiretoko to your glass where nature meets craftsmanship in every sip.', 30, NULL, '1344104a-7f28-4571-8de3-5737fd6b5943', NULL, 'published', '/products/abashiri-shiretoko-draft-green-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('41af7eb9-cfec-480b-b54c-19021f6318a3', 'Asahi Dry Zero non-Alcohol', 'Asahi Dry Zero Non-Alcohol Drink is a refreshing, crisp beverage from Asahi, offering the full taste of a classic beer without the alcohol. With 0% ABV, it delivers a smooth, clean finish and a light, satisfying bitterness that mimics the experience of a traditional dry beer. Perfect for any occasion, it’s ideal for those seeking a flavorful drink while staying alcohol-free. Enjoy chilled on its own or paired with meals, and experience the crisp, invigorating taste that Asahi is renowned for refreshment without compromise.', 19, NULL, '1344104a-7f28-4571-8de3-5737fd6b5943', NULL, 'published', '/products/asahi-dry-zero-non-alcohol-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('423f282d-6f1c-46cb-b804-068e8dc32853', 'Asahi Future Lemon Sour - Plain', 'Asahi Future Lemon Sour (Plain) is a light and refreshing alcoholic beverage from Asahi, crafted for those who enjoy a crisp, citrusy experience. With 3% ABV, this easy-to-drink lemon sour delivers a perfect balance of tangy lemon flavor and subtle sweetness, making it ideal for casual moments, social gatherings, or a relaxing refreshment after a long day. Its vibrant taste and smooth finish pair effortlessly with snacks, light meals, or simply enjoyed on its own. Experience the modern twist on a classic Japanese lemon sour with every sip.', 33, NULL, '1344104a-7f28-4571-8de3-5737fd6b5943', NULL, 'published', '/products/asahi-future-lemon-sour-plain-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('4a7d0b8f-f11b-4fe5-b00c-ab252620ab1b', 'Asahi Future lemon Sour - Original', 'Asahi Future Lemon Sour – Original is a vibrant and refreshing alcoholic drink from Asahi, crafted for fans of classic Japanese lemon sours. With 5% ABV, it delivers a lively balance of tangy lemon zest and subtle sweetness, creating a crisp, invigorating taste that’s perfect for social gatherings, casual meals, or relaxing moments. Smooth and easy to enjoy, this lemon sour pairs wonderfully with snacks, light dishes, or simply on its own, offering a modern twist on a beloved Japanese favorite.', 33, NULL, '1344104a-7f28-4571-8de3-5737fd6b5943', NULL, 'published', '/products/asahi-future-lemon-sour-original-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('ff88e894-ac4a-4994-8445-d2c0c3506671', 'Asahi Super Dry', 'Asahi Super Dry is the iconic Japanese beer known for its crisp, clean taste and smooth finish. With 5% ABV, this classic dry beer delivers a refreshing bitterness and a light, invigorating flavor that pairs perfectly with a wide range of foods. Its small 135ml can makes it convenient for on-the-go enjoyment, single servings, or sampling the renowned Asahi quality. Experience the signature “Karakuchi” dry style in every sip—a perfect balance of refreshment and sophistication.', 11, NULL, '1344104a-7f28-4571-8de3-5737fd6b5943', NULL, 'published', '/products/asahi-super-dry-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('9e336bd7-ad9d-45aa-9a73-0753b228aca5', 'KIRIN Akiaji', 'Kirin Akiaji is a seasonal Japanese beer from Kirin, celebrated for its rich flavor and smooth, satisfying finish. With 6% ABV, it delivers a perfect balance of malt sweetness and gentle bitterness, capturing the essence of autumn in every sip. Available in 350ml cans, this beer pairs beautifully with hearty dishes, grilled foods, and seasonal delicacies. Enjoy the warm, full-bodied taste that makes Kirin Akiaji a favorite for both casual moments and special gatherings, embodying the craftsmanship and tradition of Japanese brewing.', 22.5, NULL, '1344104a-7f28-4571-8de3-5737fd6b5943', NULL, 'published', '/products/kirin-akiaji-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('44f5dca8-1328-4e4a-b266-d302edbca35e', 'KIRIN Ichiban Shibori', 'Kirin Ichiban Shibori is a premium Japanese beer crafted by Kirin, a historic brewery renowned for its dedication to traditional brewing since 1888. This 350ml can features the unique “first press” method, producing a pure, smooth beer with a crisp, clean taste and a delicate balance of malt sweetness and subtle bitterness. At 5% ABV, it delivers a refreshing experience that pairs effortlessly with a wide range of dishes, from casual snacks to refined meals. Celebrated for its quality and authenticity, Kirin Ichiban Shibori embodies the perfect harmony of tradition, craftsmanship, and modern Japanese brewing excellence.', 17.5, NULL, '1344104a-7f28-4571-8de3-5737fd6b5943', NULL, 'published', '/products/kirin-ichiban-shibori-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('cdc7d7c2-e987-4ee2-a3e5-ca07e7e4f767', 'Kirin Spring Valley Silk Ale White', 'Kirin Spring Valley Silk Ale White is a sophisticated craft beer from Kirin, blending traditional Japanese brewing expertise with modern innovation. This 350ml can showcases a smooth, silky texture with a delicate balance of citrus and malt notes, delivering a refreshing yet refined taste. At 5% ABV, it offers a light, crisp finish that pairs beautifully with salads, seafood, or light appetizers. Celebrated for its elegance and approachable complexity, Spring Valley Silk Ale White embodies Kirin’s philosophy of craftsmanship, flavor innovation, and premium quality.', 22.5, NULL, '1344104a-7f28-4571-8de3-5737fd6b5943', NULL, 'published', '/products/kirin-spring-valley-silk-ale-white-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('fdf1fdb4-10d0-4ffa-967b-85d2dc16b0b7', 'Kirin Beer Harekaze', 'Kirin Beer Harekaze is a refined Japanese craft beer from Kirin, celebrated for its crisp and refreshing character. This 350ml can offers a harmonious balance of light malt sweetness and subtle bitterness, delivering a smooth, clean taste that is perfect for any occasion. At 5% ABV, it pairs effortlessly with grilled dishes, seafood, or casual snacks. Embodying the craftsmanship and tradition of Japanese brewing, Kirin Harekaze captures the essence of a clear, breezy day in every sip.', 22.5, NULL, '1344104a-7f28-4571-8de3-5737fd6b5943', NULL, 'published', '/products/kirin-beer-harekaze-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('12790235-e58d-4add-a12d-08f3ec1ac6ab', 'Kirin Spring Valley Hojun 496', 'Kirin Spring Valley Hojun 496 is a bold and full-bodied craft beer from Kirin, crafted with meticulous attention to detail to deliver richness and depth. Brewed using a generous blend of hops and malt, this 350ml can showcases a complex flavor profile with a balance of robust bitterness, subtle sweetness, and a lingering aromatic finish. At 6% ABV, it offers a satisfying, premium drinking experience that pairs perfectly with grilled meats, hearty dishes, or enjoyed on its own as a statement of craftsmanship. Representing Kirin’s innovation in modern Japanese brewing, Hojun 496 is a beer that speaks to both tradition and refinement.', 22.5, NULL, '1344104a-7f28-4571-8de3-5737fd6b5943', NULL, 'published', '/products/kirin-spring-valley-hojun496-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('92b76fd1-eb35-4dea-b1e6-f108054ab8f0', 'Sapporo Yebisu Citrus Blanc', 'Sapporo Yebisu Citrus Blanc Beer is a refined seasonal beer from Sapporo’s Yebisu line, crafted to deliver a refreshing harmony of premium malt and bright citrus notes. Brewed with select hops and accented by the gentle aroma of white wine-like citrus, this 350ml can offers a smooth, elegant taste with a crisp, clean finish. At 5% ABV, it pairs beautifully with light dishes, seafood, and fresh salads, making it an ideal choice for warm gatherings or relaxing moments. Celebrated for its balance of tradition and modern flavor, Yebisu Citrus Blanc captures the artistry of Japanese brewing in every sip.', 22.5, NULL, '1344104a-7f28-4571-8de3-5737fd6b5943', NULL, 'published', '/products/sapporo-yebisu-citrus-blanc-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('c525ea77-4f6d-4ff7-9d22-4981991c5155', 'Suntory The Premium Malt''s', 'Suntory The Premium Malt’s is a world-renowned Japanese beer from Suntory, celebrated for its rich aroma, creamy foam, and refined flavor. Brewed with carefully selected European aroma hops and high-quality malt, this 350ml can delivers a luxurious balance of smooth bitterness and elegant sweetness. At 5.5% ABV, it offers a full-bodied yet refreshing taste that pairs perfectly with both fine cuisine and casual dishes. A symbol of Japanese brewing craftsmanship, The Premium Malt’s elevates every occasion with its sophistication and quality.', 20.5, NULL, '1344104a-7f28-4571-8de3-5737fd6b5943', NULL, 'published', '/products/suntory-the-premium-malts-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('36b96502-eeaa-4e19-8e35-02f15e33f8f6', 'Suntory The Premium Malt''s Kaoru Ale', 'Suntory The Premium Malt’s Kaoru Ale is a refined Japanese ale from Suntory, crafted to highlight a delicate fragrance and smooth, elegant flavor. Brewed with carefully selected aroma hops, this 350ml can offers a fresh floral bouquet and a silky, well-balanced taste that lingers pleasantly on the palate. At 6% ABV, it delivers a richer body than standard lagers while maintaining a crisp, refreshing finish. Perfect with light dishes, seafood, or enjoyed on its own, Kaoru Ale embodies Suntory’s pursuit of premium brewing artistry.', 17.5, NULL, '1344104a-7f28-4571-8de3-5737fd6b5943', NULL, 'published', '/products/suntory-the-premium-malts-kaoru-ale-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('2bec3d77-9c35-4ae9-b521-cb6b5d594e86', 'Suntory The Premium Malt Black', 'Suntory The Premium Malt’s Black is a refined Japanese dark beer from Suntory, crafted with roasted malts to deliver a smooth, full-bodied flavor with subtle notes of chocolate and coffee. This 350ml can balances gentle bitterness with a clean, satisfying finish, offering a luxurious drinking experience. At 5.5% ABV, it pairs perfectly with hearty meals, grilled dishes, or can be savored on its own. The Premium Malt’s Black exemplifies Suntory’s mastery of brewing craftsmanship and premium taste.', 0, NULL, '1344104a-7f28-4571-8de3-5737fd6b5943', NULL, 'published', '/products/suntory-the-premium-malt-black-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('3f82b9b4-e97d-47bf-8511-b733934936cb', 'The Premium Malt''s Sea side Ale', 'Suntory The Premium Malt’s Seaside Ale is a crisp and refreshing Japanese craft beer from Suntory, inspired by the invigorating aroma of the ocean breeze. Brewed with carefully selected hops and malt, this 350ml can offers a bright, balanced flavor with subtle citrus and floral notes, delivering a smooth, clean finish. At 5.5% ABV, it pairs beautifully with seafood, light dishes, or can be enjoyed on its own for a revitalizing experience. Seaside Ale embodies Suntory’s dedication to premium craftsmanship and modern brewing artistry.', 22.5, NULL, '1344104a-7f28-4571-8de3-5737fd6b5943', NULL, 'published', '/products/the-premium-malts-sea-side-ale-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('ababf4f7-5ee8-42bf-b0c7-05543962ac74', 'Suntory The Premium Malt''s Akane-Iro Ale', 'Suntory The Premium Malt’s Akane-Iro Ale is a vibrant Japanese craft beer from Suntory, inspired by the rich hues of a sunset sky. Brewed with select hops and malt, this 350ml can delivers a smooth, well-balanced flavor with subtle fruity and floral notes, finishing crisp and refreshing. At 5.5% ABV, it pairs beautifully with light meals, grilled dishes, or can be enjoyed on its own as a sophisticated, flavorful experience. Akane-Iro Ale reflects Suntory’s dedication to artistry, premium ingredients, and modern brewing excellence.', 22.5, NULL, '1344104a-7f28-4571-8de3-5737fd6b5943', NULL, 'published', '/products/the-premium-malts-sea-side-ale-2.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('ae6cf5d6-5012-4eff-a1d3-b8680843874c', 'Suntory The Premium Malt''s Suzunone Ale', 'Suntory The Premium Malt’s Suzunone Ale is a refreshing Japanese craft beer from Suntory, inspired by the gentle, soothing tones of a summer breeze. Brewed with carefully selected hops and malt, this 350ml can offers a crisp, balanced flavor with subtle floral and fruity notes, finishing clean and invigorating. At 5.5% ABV, it pairs beautifully with light meals, seafood, or can be enjoyed on its own for a premium, revitalizing experience. Suzunone Ale embodies Suntory’s commitment to craftsmanship, quality ingredients, and modern brewing excellence.', 22.5, NULL, '1344104a-7f28-4571-8de3-5737fd6b5943', NULL, 'published', '/products/suntory-the-premium-malts-suzunone-ale-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('a922b1bd-7977-4501-882f-946907d85bda', 'Suntory The Premium Malt White', 'Suntory The Premium Malt’s Japanese Ale – White Ale is a refined Japanese craft beer from Suntory, brewed to highlight a delicate, refreshing character. This 350ml can features a smooth and silky mouthfeel with subtle notes of citrus, spice, and malt sweetness, creating a clean and elegant finish. At 5% ABV, it pairs beautifully with seafood, salads, and light appetizers, or can be enjoyed on its own for a crisp, satisfying experience. White Ale represents Suntory’s mastery of premium brewing, blending tradition with modern artistry in every sip.', 22.5, NULL, '1344104a-7f28-4571-8de3-5737fd6b5943', NULL, 'published', '/products/suntory-the-premium-malt-white-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('74242431-b7a4-4d90-9fe9-65c8bdf3831d', 'Yamaki Dashinomoto', 'Yamaki Dashinomoto is an authentic Japanese soup stock powder crafted by Yamaki, a trusted brand renowned for its dedication to quality and tradition. Made in Japan, this versatile dashi powder delivers a rich umami flavor derived from carefully selected ingredients, making it an essential base for miso soup, noodle broths, hot pots, and a wide variety of Japanese dishes. Packaged in a 1kg (35.2oz) bag, it is perfect for both home use and professional kitchens. With a shelf life of 3–9 months when stored in a cool, dry, and dark place, Yamaki Dashinomoto offers consistent flavor and convenience, bringing the true taste of Japanese cuisine to your table.', 16, NULL, 'f2f6bcab-9076-4b28-803d-37ab293aa39c', NULL, 'published', '/products/yamaki-dashinomoto-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('93716e3c-3a98-47da-a8d8-dfc7dd163b61', 'Mayonnaise Kewpie', 'Kewpie Mayonnaise is Japan’s most iconic mayonnaise, crafted by Kewpie since 1925 and beloved worldwide for its rich, creamy texture and savory umami flavor. Made with high-quality egg yolks and a unique blend of seasonings, this 1L bottle delivers a smooth, tangy taste that enhances everything from sushi and salads to sandwiches, dips, and grilled dishes. Trusted by both home cooks and professional chefs, Kewpie Mayonnaise brings out the best in every meal with its signature flavor and unmatched quality.', 9.5, NULL, 'f2f6bcab-9076-4b28-803d-37ab293aa39c', NULL, 'published', '/products/mayonnaise-kewpie-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('ccb8aec0-fb8c-471a-8edc-d878c7b6f318', 'Fresh Paste Wasabi', 'Fresh Paste Wasabi is a premium Japanese fresh grated wasabi from Kaneku, crafted to deliver the authentic heat and delicate aroma of freshly grated wasabi root. This 750g pack offers vibrant green color, smooth texture, and a pungent yet refined spiciness, perfect for enhancing sushi, sashimi, noodles, and a variety of Japanese dishes. Renowned for its consistent quality and pure flavor, Kaneku Nama Oroshi Wasabi brings the essence of traditional Japanese cuisine directly to your kitchen.', 19.5, NULL, 'f2f6bcab-9076-4b28-803d-37ab293aa39c', NULL, 'published', '/products/fresh-paste-wasabi-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('bfdac56e-e2ed-4a70-a1bf-ed852e2efcb5', 'Mizkan Cooking Sake pet', 'Mizkan Cooking Sake Pet is a high-quality Japanese cooking sake from Mizkan, crafted to enhance the flavor of a wide range of dishes. This 1.8L plastic bottle delivers a smooth, rich taste with natural sweetness, making it ideal for marinades, stir-fries, simmered dishes, and sauces. Trusted by both home cooks and professional chefs, Mizkan Cooking Liquor elevates everyday cooking with authentic Japanese flavor, adding depth and umami to your culinary creations.', 12.5, NULL, 'f2f6bcab-9076-4b28-803d-37ab293aa39c', NULL, 'published', '/products/mizkan-cooking-sake-pet-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('2396da9c-1beb-45d3-8d8a-b826f9093342', 'Mizkan Ajipon', 'Mizkan Ajipon is a classic Japanese citrus soy sauce from Mizkan, crafted to bring a bright, tangy flavor to your dishes. Made in Japan, this 1.8L bottle features a perfect balance of soy sauce and yuzu citrus, enhancing salads, grilled meats, sashimi, and hot pot dishes with a refreshing umami punch. With a shelf life of 12 months when stored in a cool, dry place (refrigerate after opening), Mizkan Ajipon delivers consistent quality and authentic Japanese taste for home cooks and professional chefs alike.', 15.5, NULL, 'f2f6bcab-9076-4b28-803d-37ab293aa39c', NULL, 'published', '/products/mizkan-ajipon-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('d190bb57-35ae-45ca-9b25-70c124373dbb', 'Dashi Pack', 'Dashi Pack is a high-quality Japanese soup stock from JFDA, crafted to deliver authentic umami flavor with ease and convenience. Made in Japan, this 1,000g pack contains 20 individual 50g portions, perfect for miso soup, noodle broths, hot pots, and a variety of Japanese dishes. Each pack ensures a rich, savory base, bringing the true taste of Japanese cuisine to your kitchen while saving time on preparation. Ideal for both home cooks and professional chefs, JFDA Dashi Pack combines convenience with premium flavor.', 28, NULL, 'f2f6bcab-9076-4b28-803d-37ab293aa39c', NULL, 'published', '/products/dashi-pack-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('e49d17d4-ec46-45fa-9fa9-c97704b5c24c', 'Shaki Shaki Wasabi', 'Shaki Shaki Wasabi is a premium Japanese wasabi paste from Kaneku, crafted to deliver the fresh, pungent heat and aromatic flavor of real wasabi root. Made in Japan, this 300g pack offers a smooth texture and vibrant green color, perfect for sushi, sashimi, noodles, and a variety of Japanese dishes. Renowned for its consistent quality and authentic taste, Shaki Shaki Wasabi brings the true essence of traditional Japanese cuisine directly to your table.', 14.5, NULL, 'f2f6bcab-9076-4b28-803d-37ab293aa39c', NULL, 'published', '/products/shaki-shaki-wasabi-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('6cad2b23-2252-4a13-8767-8bc6f2ab81fb', 'Mizkan Vinegar Meisen', 'Mizkan Vinegar Meisen is a premium Japanese vinegar from Mizkan, crafted to deliver a refined, well-balanced acidity with subtle depth of flavor. Made in Japan, this 1.8L bottle is perfect for dressings, marinades, pickling, and a variety of Japanese culinary applications. Trusted by both home cooks and professional chefs, Mizkan Vinegar Meisen enhances dishes with authentic Japanese taste and consistent quality, bringing elegance and flavor to every meal.', 13.2, NULL, 'f2f6bcab-9076-4b28-803d-37ab293aa39c', NULL, 'published', '/products/mizkan-vinegar-meisen-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('7ce8adbd-178f-4d77-b5f6-fc0457fcc37f', 'Minosannennsu Akasu Vinegar', 'Minosannennsu Akasu Vinegar is a traditional Japanese red vinegar from Uchibori, aged for three years to develop a deep, rich flavor and mellow acidity. Made in Japan, this 500ml bottle is perfect for sushi rice, dressings, marinades, and a variety of Japanese dishes, delivering authentic taste and umami complexity. Renowned for its craftsmanship and consistent quality, Minosannennsu Akasu Vinegar brings the essence of traditional Japanese brewing into your kitchen.', 15.5, NULL, 'f2f6bcab-9076-4b28-803d-37ab293aa39c', NULL, 'published', '/products/minosannennsu-akasu-vinegar-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('0b203c5e-4b9a-404d-b6ff-468039d4a2d6', 'Marukome Akamiso', 'Marukome Akamiso is a traditional Japanese red miso from Marukome, crafted to deliver a rich, savory flavor and deep umami profile. Made in Japan, this 1kg packet is perfect for miso soup, marinades, stews, and a variety of Japanese dishes, offering consistent quality and authentic taste. Renowned for its balanced saltiness and robust aroma, Marukome Akamiso brings the essence of traditional Japanese cuisine to your kitchen with every use.', 6.5, NULL, '50f52fd7-3cb2-49a9-8c58-2962349be120', NULL, 'published', '/products/marukome-akamiso-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('4f95a9dc-d492-4aab-a172-394e31f6eba6', 'Marukome Shiro Miso', 'Marukome Shiro Miso is a high-quality Japanese white miso from Marukome, crafted to deliver a mild, subtly sweet flavor and delicate umami. Made in Japan, this 1kg pack is perfect for miso soup, dressings, marinades, and a variety of Japanese dishes, offering consistent quality and authentic taste. Renowned for its smooth texture and balanced flavor, Marukome Shiro Miso brings the true essence of traditional Japanese cuisine to your kitchen.', 6.5, NULL, '50f52fd7-3cb2-49a9-8c58-2962349be120', NULL, 'published', '/products/marukome-shiro-miso-2.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('de9f03cd-0052-4f8d-8235-c8c7cb074c91', 'Hikari Miso Aka', 'Hikari Miso Aka is a traditional Japanese red miso from Hikari, crafted to deliver a robust, savory flavor with deep umami richness. Made in Japan, this 1kg pack is perfect for miso soup, marinades, stews, and a variety of Japanese dishes, ensuring consistent quality and authentic taste. Celebrated for its bold aroma and balanced saltiness, Hikari Miso Aka brings the essence of traditional Japanese cuisine directly to your kitchen.', 8, NULL, '50f52fd7-3cb2-49a9-8c58-2962349be120', NULL, 'published', '/products/hikari-miso-aka-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('c243a520-c181-4594-bc2b-16196409a8af', 'Matsushiro Miso', 'Matsushiro Miso is a premium Japanese miso crafted for rich, authentic flavor. This 1kg pack offers a well-balanced umami taste, ideal for miso soup, marinades, stews, and a variety of Japanese dishes. Renowned for its smooth texture and consistent quality, Ichikyu Matsushiro Miso brings the traditional taste of Japanese cuisine to your kitchen with every use.', 8, NULL, '50f52fd7-3cb2-49a9-8c58-2962349be120', NULL, 'published', '/products/matsushiro-miso-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('062e7967-5922-4942-97c7-c9120821830f', 'Miso with Dashi', 'Miso with Dashi is a premium Japanese miso blend from Ichikyu, infused with rich dashi for enhanced umami flavor. Made in Japan, this 750g pack is perfect for miso soup, stews, and a variety of Japanese dishes, offering a convenient way to add depth and authentic taste to your cooking. Celebrated for its balanced flavor and smooth texture, Miso with Dashi Ichikyu San brings traditional Japanese culinary excellence directly to your kitchen.', 7, NULL, '50f52fd7-3cb2-49a9-8c58-2962349be120', NULL, 'published', '/products/miso-with-dashi-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('639576ab-f5b6-43c9-8eb3-4bddab123d6e', 'Hikari Miso Shiro', 'Hikari Miso Shiro is a high-quality Japanese white miso from Hikari Miso, crafted for a mild, subtly sweet flavor with delicate umami. Made in Japan, this 1kg pack is perfect for miso soup, dressings, marinades, and a variety of Japanese dishes, delivering consistent quality and authentic taste. Renowned for its smooth texture and balanced flavor, Hikari Miso Shiro Daishinano brings the true essence of traditional Japanese cuisine to your kitchen.', 8, NULL, '50f52fd7-3cb2-49a9-8c58-2962349be120', NULL, 'published', '/products/hikari-miso-shiro-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('16f9d075-76a8-4891-bd11-ac4dd0ce8b2c', 'Hikari Awase Miso', 'Hikari Awase Miso is a premium Japanese blended miso from Hikari Miso, combining red and white miso for a balanced, rich umami flavor. This 1kg pack is perfect for miso soup, stews, marinades, and a variety of Japanese dishes, offering versatility and authentic taste. Known for its smooth texture and harmonious flavor profile, Hikari Awase Miso brings the essence of traditional Japanese cuisine to your kitchen.', 9.5, NULL, '50f52fd7-3cb2-49a9-8c58-2962349be120', NULL, 'published', '/products/hikari-awase-miso-1.jpg', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z'),
  ('41797bac-965f-4b8c-a98b-03be1f1dc867', 'Strawberry Daifuku', 'Strawberry Daifuku is a traditional Japanese confection that combines soft, chewy mochi with a luscious strawberry filling for a perfect balance of sweetness and freshness. Each box contains 6 pieces, crafted with care to deliver a smooth texture and a delightful burst of fruity flavor in every bite. Enjoyed as a dessert or afternoon treat, Strawberry Daifuku offers an authentic taste of Japanese wagashi, blending elegance and indulgence in a single bite.', 19, NULL, 'a7964c0a-2c0f-4b98-95df-c7178f3c6f6c', NULL, 'published', '/products/Strawberry-Daifuku.webp', NULL, 4.5, '2026-07-24T04:42:15.150Z', '2026-07-24T04:42:15.150Z');
